// ==================== Agent UI Context ====================
// 头像配置类型（从 runtime.tsx 迁移）
export type AvatarConfig =
  | string
  | { type: "text"; text: string }
  | { type: "image"; src: string; alt?: string };

export interface AvatarSettings {
  /** 用户头像 */
  user?: AvatarConfig;
  /** 助手头像 */
  agent?: AvatarConfig;
}

/** 标准化头像格式 */
interface NormalizedAvatar {
  kind: "image" | "text";
  value: string;
  alt?: string;
}

/**
 * 标准化头像配置
 * @param a 头像配置
 * @returns 标准化后的头像，或 undefined
 */
export function normalizeAvatar(a: AvatarConfig | undefined | null): NormalizedAvatar | undefined {
  if (!a) return undefined;
  if (typeof a === "string") {
    if (!a) return undefined;
    const looksLikeImage =
      /^(https?:\/\/|data:|\/|\.\/|\.\.\/|blob:)/i.test(a) ||
      /\.(png|jpe?g|gif|webp|svg|bmp|avif|ico)$/i.test(a);
    return looksLikeImage ? { kind: "image", value: a } : { kind: "text", value: a };
  }
  return a.type === "image"
    ? { kind: "image", value: a.src, alt: a.alt }
    : { kind: "text", value: a.text };
}

/** Agent UI 上下文 - 仅存储 UI 专属配置（头像） */
interface AgentUIContextValue {
  /** 头像设置 */
  avatar?: AvatarSettings;
}

const AgentUIContext = createContext<AgentUIContextValue>({});

/** Store extras 中的业务参数类型 */
type AgentExtras = {
  agentId: string;
  setAgentId: (id: string) => void;
  preamble?: string;
  renderRegistry?: RenderRegistry;
  onShareThread?: (messages: readonly ThreadMessage[]) => void;
  isTaskRuntime?: boolean;
  /** 询问模式：待答复的交互请求 */
  interactionRequests?: AgentInteractionRequest[];
  /** 回复后端（POST /messages/{id}/permission-reply） */
  replyInteraction?: (
    request: AgentInteractionRequest,
    action: InteractionReplyAction,
    updatedInput?: Record<string, unknown>,
  ) => Promise<void>;
};

/**
 * Agent UI Hook - 从 store extras 和 context 中合并读取业务参数
 */
const useAgentUI = (): AgentUIContextValue & AgentExtras => {
  const { avatar } = useContext(AgentUIContext);
  const extras = useAuiState(s => s.thread.extras) as AgentExtras | undefined;
  return {
    avatar,
    agentId: extras?.agentId ?? '',
    setAgentId: extras?.setAgentId ?? (() => {}),
    preamble: extras?.preamble,
    renderRegistry: extras?.renderRegistry,
    onShareThread: extras?.onShareThread,
    isTaskRuntime: extras?.isTaskRuntime,
    interactionRequests: extras?.interactionRequests,
    replyInteraction: extras?.replyInteraction,
  };
};

/**
 * Agent UI Provider - 提供 UI 专属配置（头像）
 */
export const AgentUIProvider: FC<{
  children: ReactNode;
  avatar?: AvatarSettings;
}> = ({ children, avatar }) => {
  return (
    <AgentUIContext.Provider value={{ avatar }}>
      {children}
    </AgentUIContext.Provider>
  );
};

// ==================== 头像渲染辅助 ====================

/** 检查是否启用头像模式 */
const useAvatarMode = () => {
  const { avatar } = useAgentUI();
  return !!(avatar && (avatar.user || avatar.agent));
};

/** 头像渲染：avatar 模式下未配置的一方回退为默认文字头像（用户 U / 助手 A） */
const MessageAvatar: FC<{ kind: "user" | "agent"; className?: string }> = ({
  kind,
  className,
}) => {
  const { avatar } = useAgentUI();
  const raw = kind === "user" ? avatar?.user : avatar?.agent;
  const avatarConfig =
    normalizeAvatar(raw) ??
    { kind: "text" as const, value: kind === "user" ? "U" : "A" };
  return (
    <div
      className={cn(
        "bg-muted text-foreground/70 flex size-8 shrink-0 select-none items-center justify-center overflow-hidden rounded-full text-xs font-medium",
        className,
      )}
    >
      {avatarConfig.kind === "image" ? (
        <img
          src={avatarConfig.value}
          alt={avatarConfig.alt ?? (kind === "user" ? "用户头像" : "助手头像")}
          className="size-full object-cover"
        />
      ) : (
        <span className="truncate px-1">{avatarConfig.value}</span>
      )}
    </div>
  );
};

const Logo: FC = () => {
  return (
    <div className="flex items-center gap-2 px-2 text-sm font-medium">
      <span className="text-foreground/90">kesi-ui</span>
    </div>
  );
};

/** Agent 选择下拉列表 */
export const AgentSelect: FC = () => {
  const { agentId, setAgentId } = useAgentUI();
  const [agents, setAgents] = useState<Array<{ value: string; label: string }>>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const api = createAPI({ name: 'eap/agents' });
    api.fetch('').then(({ json }: any) => {
      const items = Array.isArray(json) ? json : [];
      setAgents(items.map((a: any) => ({ value: a.id, label: a.title || a.name || a.id })));
    }).catch(() => {
      setAgents([]);
    }).finally(() => setLoading(false));
  }, []);

  // 与 ThreadListSelect 同理：agentId 若不在当前可选项中（空字符串、列表尚未加载完成、
  // 或已配置的 agent 不在返回列表里），直接传给 Radix 会找不到匹配的 SelectItem 而显示空白。
  // 归为 undefined 让 SelectValue 正常显示 placeholder。
  const selectValue = agentId && agents.some((a) => a.value === agentId) ? agentId : undefined;

  return (
    <Select value={selectValue} onValueChange={setAgentId}>
      <SelectTrigger className="aui-agent-select h-8 w-full border-0 bg-transparent px-3 text-sm shadow-none hover:bg-accent">
        <SelectValue placeholder="选择 Agent" />
      </SelectTrigger>
      <SelectContent>
        {loading && (
          <SelectItem value="__loading__" disabled>加载中...</SelectItem>
        )}
        {!loading && agents.length === 0 && (
          <SelectItem value="__empty__" disabled>无可用 Agent</SelectItem>
        )}
        {agents.map((a) => (
          <SelectItem key={a.value} value={a.value}>{a.label}</SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
};

export const Sidebar: FC<{ collapsed?: boolean; title?: string; showAgentSelect?: boolean }> = ({ collapsed, title, showAgentSelect }) => {
