        >
          <span
            className={cn(
              "text-foreground/90 ml-2 text-sm font-medium whitespace-nowrap transition-opacity duration-200",
              collapsed && "opacity-0",
            )}
          >
            {title}
          </span>
        </div>
      )}
      {collapsed ? (
        <ThreadListPrimitive.New asChild>
          <TooltipIconButton
            tooltip="新对话"
            side="right"
            variant="ghost"
            size="icon"
            className="mt-1 ml-2 size-8"
          >
            <PlusIcon className="size-4" />
          </TooltipIconButton>
        </ThreadListPrimitive.New>
      ) : (
        <div className="relative w-65 flex-1 overflow-y-auto p-3">
          {showAgentSelect && <AgentSelect />}
          <ThreadList />
        </div>
      )}
    </aside>
  );
};

