  )
  const answers = React.useMemo(
    () => answerControls.filter((registration) => !registration.disabled),
    [answerControls]
  )
  const answered = answers.some((answer) =>
    selectedAnswerIds.includes(answer.id)
  )
  const status: QuestionnaireItemStatus = skipped
    ? "skipped"
    : answered
      ? "answered"
      : "unanswered"
  const intentionallySkipped = status === "skipped" && !required
  const valid =
    disabled ||
    intentionallySkipped ||
    (!externallyInvalid && status === "answered")
  const invalid =
    !disabled &&
    !intentionallySkipped &&
    (externallyInvalid || (validationAttempted && !valid))
  const hasInputAnswer = answers.some((answer) => answer.type === "input")
  const previousStatusRef = React.useRef(status)
  const itemDefinition = itemDefinitionByName?.get(name)
  const shortcutByChoiceValue = React.useMemo(
    () =>
      itemDefinitionByName
        ? getShortcutByChoiceValue(itemDefinition, shortcuts)
        : null,
    [itemDefinition, itemDefinitionByName, shortcuts]
  )
  const shortcutByAnswerId = React.useMemo(() => {
    if (shortcutByChoiceValue) {
      return new Map<string, string>()
    }

    const keys = getShortcutKeys(shortcuts)
    const shortcutAnswers = answers.filter((answer) => answer.type === "choice")

    return new Map(
      shortcutAnswers
        .slice(0, keys.length)
        .map((answer, index) => [answer.id, keys[index]])
    )
  }, [answers, shortcutByChoiceValue, shortcuts])

  const registerAnswerControl = React.useCallback(
    (registration: AnswerControlRegistration) => {
      setAnswerControlRegistrations((currentRegistrations) => [
        ...currentRegistrations.filter(
          (currentRegistration) =>
            currentRegistration.element !== registration.element &&
            currentRegistration.id !== registration.id
        ),
        registration,
      ])

      return () => {
        setAnswerControlRegistrations((currentRegistrations) =>
          currentRegistrations.filter(
            (currentRegistration) => currentRegistration !== registration
          )
        )
      }
    },
    []
  )

  React.useLayoutEffect(() => {
    if (previousStatusRef.current === status) {
      return
    }

    previousStatusRef.current = status

    onStatusChange?.(status)
  }, [onStatusChange, status])

  const updateAnswerSelected = React.useCallback(
    (answerId: string, selected: boolean) => {
      setSelectedAnswerIds((currentAnswerIds) => {
        if (!selected) {
          return currentAnswerIds.filter(
            (currentAnswerId) => currentAnswerId !== answerId
          )
        }

        if (!multiple) {
          return [answerId]
        }

        return currentAnswerIds.includes(answerId)
          ? currentAnswerIds
          : [...currentAnswerIds, answerId]
      })
    },
    [multiple]
  )
  const setAnswerSelectionFromInteraction = React.useCallback(
    (answerId: string, selected: boolean) => {
      setSkipped(false)
      updateAnswerSelected(answerId, selected)
    },
    [updateAnswerSelected]
  )
  const syncControlledAnswerSelection = React.useCallback(
    (answerId: string, selected: boolean) => {
      if (selected) {
        setSkipped(false)
      }

      updateAnswerSelected(answerId, selected)
    },
    [updateAnswerSelected]
  )

  const registerAnswerSelection = React.useCallback(
    (answerId: string, defaultSelected: boolean) => {
      if (defaultSelected) {
        defaultSelectedAnswerIdsRef.current = [
          ...defaultSelectedAnswerIdsRef.current.filter(
            (currentAnswerId) => currentAnswerId !== answerId
          ),
          answerId,
        ]
        setSelectedAnswerIds((currentAnswerIds) => {
          if (!multipleRef.current) {
            return currentAnswerIds.length ? currentAnswerIds : [answerId]
          }

          return currentAnswerIds.includes(answerId)
            ? currentAnswerIds
            : [...currentAnswerIds, answerId]
        })
      }

      return () => {
        defaultSelectedAnswerIdsRef.current =
          defaultSelectedAnswerIdsRef.current.filter(
            (currentAnswerId) => currentAnswerId !== answerId
          )
        setSelectedAnswerIds((currentAnswerIds) =>
          currentAnswerIds.filter(
            (currentAnswerId) => currentAnswerId !== answerId
          )
        )
      }
    },
    []
  )
  const setAnswerDefault = React.useCallback(
    (answerId: string, defaultSelected: boolean) => {
      if (defaultSelected) {
        defaultSelectedAnswerIdsRef.current =
          defaultSelectedAnswerIdsRef.current.includes(answerId)
            ? defaultSelectedAnswerIdsRef.current
            : [...defaultSelectedAnswerIdsRef.current, answerId]
        return
      }

      defaultSelectedAnswerIdsRef.current =
        defaultSelectedAnswerIdsRef.current.filter(
          (currentAnswerId) => currentAnswerId !== answerId
        )
    },
    []
  )

  const registerDescription = React.useCallback(
    (registeredDescriptionId: string) => {
      setDescriptionIds((currentDescriptionIds) =>
        currentDescriptionIds.includes(registeredDescriptionId)
          ? currentDescriptionIds
          : [...currentDescriptionIds, registeredDescriptionId]
      )

      return () => {
        setDescriptionIds((currentDescriptionIds) =>
          currentDescriptionIds.filter(
            (currentDescriptionId) =>
              currentDescriptionId !== registeredDescriptionId
          )
        )
      }
    },
    []
  )

  const registerError = React.useCallback((registeredErrorId: string) => {
    setErrorIds((currentErrorIds) =>
      currentErrorIds.includes(registeredErrorId)
        ? currentErrorIds
        : [...currentErrorIds, registeredErrorId]
    )

    return () => {
      setErrorIds((currentErrorIds) =>
        currentErrorIds.filter(
          (currentErrorId) => currentErrorId !== registeredErrorId
        )
      )
    }
  }, [])

  const validate = React.useCallback(() => {
    setValidationAttempted(true)

    if (!valid) {
      return false
    }

    if (!nativeValidation) {
      return true
    }

    const invalidAnswer = answers.find(
      (answer) =>
        isAnswerFilled(answer) &&
        answer.element.willValidate &&
        !answer.element.validity.valid
    )

    if (!invalidAnswer) {
      return true
    }

    invalidAnswer.element.focus()
    invalidAnswer.element.reportValidity()

    return false
  }, [answers, nativeValidation, valid])

  const focus = React.useCallback(() => {
    element?.focus()
  }, [element])

  const focusInvalid = React.useCallback(() => {
    const selectedInput = element?.querySelector<HTMLInputElement>(
      "input[data-filled][name]:not(:disabled)"
    )
    const firstControl = element?.querySelector<HTMLElement>(
      "input:not([type=hidden]):not(:disabled), textarea:not(:disabled)"
    )

    ;(selectedInput ?? firstControl ?? element)?.focus()
  }, [element])

  const reset = React.useCallback(() => {
    setValidationAttempted(false)
    setSkipped(false)
    setSelectedAnswerIds(
      multiple
        ? [...defaultSelectedAnswerIdsRef.current]
        : defaultSelectedAnswerIdsRef.current.slice(0, 1)
    )
    setResetVersion((version) => version + 1)
  }, [multiple])

  const skip = React.useCallback(() => {
    if (required) {
      return
    }

    setSelectedAnswerIds([])
    setSkipped(true)
  }, [required])

  React.useLayoutEffect(() => {
    const wasMultiple = previousMultipleRef.current
    previousMultipleRef.current = multiple

    if (!wasMultiple || multiple) {
      return
    }

    setSelectedAnswerIds((currentAnswerIds) => {
      const selectedAnswer = answers.find((answer) =>
        currentAnswerIds.includes(answer.id)
      )

      return selectedAnswer ? [selectedAnswer.id] : []
    })
  }, [answers, multiple])

  const getAnswerByElement = React.useCallback(
    (answerElement: Element) =>
      answers.find((answer) => answer.element === answerElement) ?? null,
    [answers]
  )
  const getAnswerByShortcut = React.useCallback(
    (shortcut: string) => {
      if (shortcutByChoiceValue) {
        const choiceValue = Array.from(shortcutByChoiceValue.entries()).find(
          ([, choiceShortcut]) => choiceShortcut === shortcut
        )?.[0]

        return (
          answers.find(
            (answer) => answer.type === "choice" && answer.value === choiceValue
          ) ?? null
        )
      }

      const answerId = Array.from(shortcutByAnswerId.entries()).find(
        ([, answerShortcut]) => answerShortcut === shortcut
      )?.[0]

      return answers.find((answer) => answer.id === answerId) ?? null
    },
    [answers, shortcutByAnswerId, shortcutByChoiceValue]
  )
  const moveAnswerFocus = React.useCallback(
    (currentElement: Element, direction: "next" | "previous") => {
      const currentIndex = answers.findIndex(
        (answer) => answer.element === currentElement
      )
      const currentAnswer =
        currentIndex < 0 ? null : (answers[currentIndex] ?? null)

      if (
        !answers.length ||
        (isTextEntryTarget(currentElement) &&
          !isEmptyNavigableInput(currentAnswer)) ||
        (currentIndex < 0 && currentElement !== element)
      ) {
        return false
      }

      const nextAnswer =
        currentIndex < 0
          ? (answers.find(isAnswerFilled) ??
            (direction === "next" ? answers[0] : answers[answers.length - 1]))
          : answers[
              (currentIndex +
                (direction === "next" ? 1 : -1) +
                answers.length) %
                answers.length
            ]

      if (!nextAnswer || nextAnswer.element === currentElement) {
        return false
      }

      if (
        currentIndex >= 0 &&
        isRadioTarget(currentElement) &&
        isRadioTarget(nextAnswer.element)
      ) {
        return false
      }

      nextAnswer.element.focus()

      if (nextAnswer.type === "choice" && isRadioTarget(nextAnswer.element)) {
        nextAnswer.element.click()
      }

      return true
    },
    [answers, element]
  )

  React.useLayoutEffect(() => {
    if (!element) {
      return
    }

    return registerItem({
      choices: answerControls.flatMap((answer) =>
        answer.type === "choice"
          ? [{ disabled: answer.ownDisabled, value: answer.value }]
          : []
      ),
      disabled,
      element,
      focus,
      focusInvalid,
      getAnswerByElement,
      getAnswerByShortcut,
      moveAnswerFocus,
      name,
      required,
      reset,
      skip,
      status,
      validate,
    })
  }, [
    answerControls,
    disabled,
    element,
    focus,
    focusInvalid,
    getAnswerByElement,
    getAnswerByShortcut,
    moveAnswerFocus,
    name,
    registerItem,
    required,
    reset,
    skip,
    status,
    validate,
  ])

  const context = React.useMemo<QuestionnaireItemContextValue>(
    () => ({
      active,
      disabled,
      hasInputAnswer,
      invalid,
      multiple,
      name,
      registerAnswerControl,
      registerAnswerSelection,
      registerDescription,
      registerError,
      required,
      resetVersion,
      selectedAnswerIds,
      setAnswerDefault,
      setAnswerSelectionFromInteraction,
      shortcutByAnswerId,
      shortcutByChoiceValue,
      shortcuts,
      status,
      syncControlledAnswerSelection,
    }),
    [
      active,
      disabled,
      hasInputAnswer,
      invalid,
      multiple,
      name,
      registerAnswerControl,
      registerAnswerSelection,
      registerDescription,
      registerError,
      required,
      resetVersion,
      selectedAnswerIds,
      setAnswerDefault,
      setAnswerSelectionFromInteraction,
      shortcutByAnswerId,
      shortcutByChoiceValue,
      shortcuts,
      status,
      syncControlledAnswerSelection,
    ]
  )
  const setItemRef = React.useCallback(
    (nextElement: HTMLFieldSetElement | null) => {
      setElement(nextElement)
      composeRefs(ref)?.(nextElement)
    },
    [ref]
  )
  const describedBy =
    [...descriptionIds, ...(invalid ? errorIds : []), ariaDescribedBy]
      .filter(Boolean)
      .join(" ") || undefined
  const keyShortcuts =
    [
      ariaKeyShortcuts,
      active ? "Meta+Enter Control+Enter" : undefined,
      active && answers.length ? "ArrowUp ArrowDown" : undefined,
      active && !first ? "ArrowLeft" : undefined,
      active && !last && status !== "unanswered" ? "ArrowRight" : undefined,
    ]
      .filter(Boolean)
      .join(" ") || undefined
  const state: QuestionnaireItemState = {
    active,
    disabled,
    invalid,
    multiple,
    required,
    status,
  }

  return {
    context,
    itemProps: {
      "aria-describedby": describedBy,
      "aria-invalid": invalid || undefined,
      "aria-keyshortcuts": keyShortcuts,
      disabled,
      hidden: !active,
      inert: !active,
      ref: setItemRef,
      tabIndex: -1,
    },
    state,
  }
}

export { useQuestionnaireItem }

import * as React from "react"

import { composeRefs } from "./use-render"
import {
  createQuestionnaireCollection,
  getCollectionDefinitionWarnings,
  getCollectionRegistrationWarnings,
  getInitialItemName,
} from "./collection"
import type {
  ItemRegistration,
  PendingFocus,
  QuestionnaireContextValue,
  QuestionnaireRootProps,
  QuestionnaireRootState,
} from "./types"
import {
  compareItemOrder,
  getShortcutFromKey,
  isAnswerFilled,
  isRadioTarget,
  isTextEntryTarget,
} from "./utils"

type UseQuestionnaireRootParameters = Pick<
  QuestionnaireRootProps,
  | "defaultItem"
  | "item"
  | "items"
  | "noValidate"
  | "onItemChange"
  | "onReset"
  | "onSubmit"
  | "ref"
  | "shortcuts"
>

function useQuestionnaireRoot({
  defaultItem,
  item: controlledItem,
  items: itemDefinitions,
  noValidate,
  onItemChange,
  onReset,
  onSubmit,
  ref,
  shortcuts: shortcutMode,
}: UseQuestionnaireRootParameters) {
  const collection = React.useMemo(
    () => createQuestionnaireCollection(itemDefinitions),
    [itemDefinitions]
  )
  const [registrations, setRegistrations] = React.useState<ItemRegistration[]>(
    []
  )
  const [uncontrolledItem, setUncontrolledItem] = React.useState<string | null>(
    () => getInitialItemName(collection, defaultItem)
  )
  const [rootElement, setRootElement] = React.useState<HTMLFormElement | null>(
    null
  )
  const [domVersion, setDomVersion] = React.useState(0)
  const pendingFocusRef = React.useRef<PendingFocus | null>(null)
  const controlled = controlledItem !== undefined
  const activeItemName = controlled ? controlledItem : uncontrolledItem
  const previousActiveItemNameRef = React.useRef(activeItemName)
  const nativeValidation = noValidate === false
  const shortcuts = shortcutMode ?? null

  const activeWarningsRef = React.useRef(new Set<string>())

  React.useLayoutEffect(() => {
    if (process.env.NODE_ENV === "production") {
      return
    }

    if (!collection || !rootElement) {
      activeWarningsRef.current.clear()
      return
    }

    let cancelled = false

    queueMicrotask(() => {
      if (cancelled) {
        return
      }

      const warnings = [
        ...getCollectionDefinitionWarnings(collection, defaultItem),
        ...getCollectionRegistrationWarnings(
          collection,
          registrations,
          shortcuts
        ),
      ]
      const activeWarnings = new Set(warnings)

      activeWarnings.forEach((warning) => {
        if (!activeWarningsRef.current.has(warning)) {
          console.warn(`[Questionnaire] ${warning}`)
        }
      })

      activeWarningsRef.current = activeWarnings
    })

    return () => {
      cancelled = true
    }
  }, [collection, defaultItem, registrations, rootElement, shortcuts])

  React.useLayoutEffect(() => {
    if (!rootElement || typeof MutationObserver === "undefined") {
      return
    }

    const observer = new MutationObserver(() => {
      setDomVersion((version) => version + 1)
    })

    observer.observe(rootElement, { childList: true, subtree: true })

    return () => observer.disconnect()
  }, [rootElement])

  const runtimeItems = React.useMemo(
    () =>
      registrations
        .filter((registration) => !registration.disabled)
        .sort(compareItemOrder),
    [domVersion, registrations]
  )
  const runtimeItemByName = React.useMemo(
    () =>
      new Map(
        runtimeItems.map((runtimeItem) => [runtimeItem.name, runtimeItem])
      ),
    [runtimeItems]
  )
  const logicalItems = collection?.enabledItems ?? runtimeItems
  const currentIndex = logicalItems.findIndex(
    (logicalItem) => logicalItem.name === activeItemName
  )
  const activeItem =
    currentIndex < 0 || !activeItemName
      ? null
      : (runtimeItemByName.get(activeItemName) ?? null)
  const activeDefinition = activeItemName
    ? collection?.itemByName.get(activeItemName)
    : undefined
  const activeItemRequired =
    currentIndex < 0
      ? null
      : activeDefinition
        ? Boolean(activeDefinition.required)
        : (activeItem?.required ?? false)
  const activeItemStatus =
    currentIndex < 0
      ? null
      : (activeItem?.status ?? (activeItemName ? "unanswered" : null))
  const orderedRegistrations = React.useMemo(
    () =>
      collection
        ? collection.enabledItems.flatMap((definition) => {
            const registration = runtimeItemByName.get(definition.name)

            return registration ? [registration] : []
          })
        : runtimeItems,
    [collection, runtimeItemByName, runtimeItems]
  )
  const total = logicalItems.length
  const current = currentIndex < 0 ? 0 : currentIndex + 1
  const first = total > 0 && currentIndex === 0
  const last = total > 0 && currentIndex === total - 1

  const setItem = React.useCallback(
    (nextItem: string, focusTarget: PendingFocus["target"] = "item") => {
      if (nextItem === activeItemName) {
        return
      }

      pendingFocusRef.current = {
        name: nextItem,
        target: focusTarget,
      }

      if (!controlled) {
        setUncontrolledItem(nextItem)
      }

      onItemChange?.(nextItem)
    },
    [activeItemName, controlled, onItemChange]
  )

  React.useLayoutEffect(() => {
    if (total === 0) {
      return
    }

    if (currentIndex < 0) {
      if (!controlled && activeItemName === null) {
        setUncontrolledItem(logicalItems[0].name)
        return
      }

      setItem(logicalItems[0].name)
      return
    }

    const pendingFocus = pendingFocusRef.current
    const activeItemChanged =
      previousActiveItemNameRef.current !== activeItemName

    previousActiveItemNameRef.current = activeItemName

    if (!pendingFocus || pendingFocus.name !== activeItemName) {
      if (controlled && activeItemChanged) {
        pendingFocusRef.current = null
        activeItem?.focus()
      }

      return
    }

    if (pendingFocus.target === "invalid") {
      activeItem?.focusInvalid()
    } else {
      activeItem?.focus()
    }

    pendingFocusRef.current = null
  }, [
    activeItem,
    activeItemName,
    controlled,
    currentIndex,
    logicalItems,
    setItem,
    total,
  ])

  const registerItem = React.useCallback((registration: ItemRegistration) => {
    setRegistrations((currentRegistrations) => [
      ...currentRegistrations.filter(
        (currentRegistration) =>
          currentRegistration.element !== registration.element &&
          currentRegistration.name !== registration.name
      ),
      registration,
    ])

    return () => {
      setRegistrations((currentRegistrations) =>
        currentRegistrations.filter(
          (currentRegistration) => currentRegistration !== registration
        )
      )
    }
  }, [])

  const goPrevious = React.useCallback(() => {
    if (currentIndex <= 0) {
      return
    }

    setItem(logicalItems[currentIndex - 1].name)
  }, [currentIndex, logicalItems, setItem])

  const goNext = React.useCallback(() => {
    if (!activeItem || currentIndex >= total - 1) {
      return
    }

    if (!activeItem.validate()) {
      activeItem.focusInvalid()
      return
    }

    setItem(logicalItems[currentIndex + 1].name)
  }, [activeItem, currentIndex, logicalItems, setItem, total])

  const confirmCurrent = React.useCallback(() => {
    if (!activeItem) {
      return
    }

    if (!activeItem.validate()) {
      activeItem.focusInvalid()
      return
    }

    if (last) {
      rootElement?.requestSubmit()
      return
    }

    setItem(logicalItems[currentIndex + 1].name)
  }, [activeItem, currentIndex, last, logicalItems, rootElement, setItem])

  const skipCurrent = React.useCallback(() => {
    if (!activeItem || activeItem.required) {
      return
    }

    activeItem.skip()

    if (!last) {
      setItem(logicalItems[currentIndex + 1].name)
      return
    }

    queueMicrotask(() => {
      rootElement?.requestSubmit()
    })
  }, [activeItem, currentIndex, last, logicalItems, rootElement, setItem])

  function handleReset(event: React.FormEvent<HTMLFormElement>) {
    onReset?.(event)

    if (event.defaultPrevented) {
      return
    }

    for (const registration of registrations) {
      registration.reset()
    }

    const resetItemName = collection
      ? getInitialItemName(collection, defaultItem)
      : (runtimeItems.find((registration) => registration.name === defaultItem)
          ?.name ?? runtimeItems[0]?.name)

    if (resetItemName) {
      setItem(resetItemName)
    }
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    const firstInvalidItem = orderedRegistrations.find(
      (registration) => !registration.validate()
    )

    if (firstInvalidItem) {
      event.preventDefault()
      setItem(firstInvalidItem.name, "invalid")

      if (firstInvalidItem.name === activeItemName) {
        firstInvalidItem.focusInvalid()
        pendingFocusRef.current = null
      }

      return
    }

    onSubmit?.(event)
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLFormElement>) {
    if (
      event.defaultPrevented ||
      event.nativeEvent.isComposing ||
      event.keyCode === 229 ||
      !activeItem ||
      !(event.target instanceof Element)
    ) {
      return
    }

    if (
      event.key === "Enter" &&
      (event.metaKey || event.ctrlKey) &&
      !event.altKey &&
      !event.shiftKey
    ) {
      event.preventDefault()

      if (!event.repeat) {
        confirmCurrent()
      }

      return
    }

    if (event.metaKey || event.ctrlKey || event.altKey) {
      return
    }

    if (event.key === "ArrowUp" || event.key === "ArrowDown") {
      const moved = activeItem.moveAnswerFocus(
        event.target,
        event.key === "ArrowDown" ? "next" : "previous"
      )

      if (moved) {
        event.preventDefault()
        return
      }
    }

    if (
      (event.key === "ArrowLeft" || event.key === "ArrowRight") &&
      !isTextEntryTarget(event.target) &&
      !isRadioTarget(event.target)
    ) {
      event.preventDefault()

      if (event.repeat) {
        return
      }

      if (event.key === "ArrowLeft") {
        goPrevious()
      } else if (activeItem.status !== "unanswered") {
        goNext()
      }

      return
    }

    if (event.key === "Enter") {
      const answer = activeItem.getAnswerByElement(event.target)

      if (!answer) {
        return
      }

      event.preventDefault()

      if (!event.repeat && isAnswerFilled(answer)) {
        confirmCurrent()
      }

      return
    }

    if (!shortcuts || isTextEntryTarget(event.target)) {
      return
    }

    const shortcut = getShortcutFromKey(event.key, shortcuts)
    const answer = shortcut ? activeItem.getAnswerByShortcut(shortcut) : null

    if (!answer) {
      return
    }

    event.preventDefault()

    if (event.repeat) {
      return
    }

    answer.element.focus()

    if (answer.type === "choice") {
      answer.element.click()
    }
  }

  const state: QuestionnaireRootState = {
    current,
    first,
    last,
    total,
  }
  const context = React.useMemo<QuestionnaireContextValue>(
    () => ({
      ...state,
      activeItem,
      activeItemName,
      activeItemRequired,
      activeItemStatus,
      domVersion,
      goNext,
      goPrevious,
      itemDefinitionByName: collection?.itemByName ?? null,
      nativeValidation,
      registerItem,
      shortcuts,
      skipCurrent,
    }),
    [
      activeItem,
      activeItemName,
      activeItemRequired,
      activeItemStatus,
      collection,
      current,
      domVersion,
      first,
      goNext,
      goPrevious,
      last,
      nativeValidation,
      registerItem,
      shortcuts,
      skipCurrent,
      total,
    ]
  )
  const setRootRef = React.useCallback(
    (element: HTMLFormElement | null) => {
      setRootElement(element)
      composeRefs(ref)?.(element)
    },
    [ref]
  )

  return {
    context,
    rootProps: {
      "data-shortcuts": shortcuts ?? undefined,
      onKeyDown: handleKeyDown,
      onReset: handleReset,
      onSubmit: handleSubmit,
      ref: setRootRef,
    },
    state,
  }
}

export { useQuestionnaireRoot }

﻿// A poor man's version of base-ui useRender.
// see https://base-ui.com/react/utils/use-render.
// TODO: Replace if base-ui useRender is published as a package.
import * as React from "react"

type RenderState = Record<string, unknown>

type RenderFunction<TState extends RenderState> = (
  props: Record<string, unknown>,
  state: TState
) => React.ReactElement | null

type RenderProp<TState extends RenderState> =
  | React.ReactElement
  | RenderFunction<TState>

type StateAttributesMapping<TState extends RenderState> = Partial<{
  [K in keyof TState]: (
    value: TState[K]
  ) => Record<string, string | undefined> | null | undefined
}>

type UseRenderComponentProps<
  TElement extends React.ElementType,
  TState extends RenderState = RenderState,
> = React.ComponentPropsWithRef<TElement> & {
  render?: RenderProp<TState>
}

type UseRenderOptions<
  TElement extends React.ElementType,
  TState extends RenderState,
> = {
  defaultTagName: TElement
  props?: React.ComponentPropsWithRef<TElement>
  render?: RenderProp<TState>
  state?: TState
  stateAttributesMapping?: StateAttributesMapping<TState>
}

function useRender<
  TElement extends React.ElementType,
  TState extends RenderState = RenderState,
>({
  defaultTagName,
  props,
  render,
  state = {} as TState,
  stateAttributesMapping,
}: UseRenderOptions<TElement, TState>) {
  const elementProps = mergeProps<TElement>(
    getStateAttributes(state, stateAttributesMapping),
    props
  )

  if (!render) {
    return React.createElement(defaultTagName, elementProps)
  }

  if (typeof render === "function") {
    return render(elementProps, state)
  }

  if (!React.isValidElement(render)) {
    return null
  }

  const renderProps = render.props as Record<string, unknown>
  const propsWithRenderProps = mergeProps<TElement>(elementProps, renderProps)
  const propsWithRef = {
    ...propsWithRenderProps,
    ref: composeRefs(
      elementProps.ref as React.Ref<unknown> | undefined,
      renderProps.ref as React.Ref<unknown> | undefined
    ),
  }

  return React.cloneElement(
    render,
    propsWithRef as React.Attributes & Record<string, unknown>
  )
}

function mergeProps<TElement extends React.ElementType>(
  ...sources: Array<
    React.ComponentPropsWithRef<TElement> | Record<string, unknown> | undefined
  >
) {
  const result: Record<string, unknown> = {}

  for (const source of sources) {
    if (!source) {
      continue
    }

    const sourceProps = source as Record<string, unknown>

    for (const key of Object.keys(sourceProps)) {
      const value = sourceProps[key]

      if (value === undefined) {
        continue
      }

      const current = result[key]

      if (key === "className") {
        result[key] = [current, value].filter(Boolean).join(" ")
      } else if (key === "style") {
        result[key] = {
          ...(current as React.CSSProperties | undefined),
          ...(value as React.CSSProperties | undefined),
        }
      } else if (key === "ref") {
        result[key] = composeRefs(
          current as React.Ref<unknown> | undefined,
          value as React.Ref<unknown> | undefined
        )
      } else if (
        isEventHandler(key) &&
        typeof current === "function" &&
        typeof value === "function"
      ) {
        result[key] = composeEventHandlers(
          value as EventHandler,
          current as EventHandler
        )
      } else {
        result[key] = value
      }
    }
  }

  return result as React.ComponentPropsWithRef<TElement>
}

function getStateAttributes<TState extends RenderState>(
  state: TState,
  mapping?: StateAttributesMapping<TState>
) {
  const props: Record<string, unknown> = {}

  for (const key of Object.keys(state) as Array<keyof TState>) {
    const value = state[key]
    const attributes = mapping?.[key]?.(value)

    if (attributes) {
      Object.assign(props, attributes)
      continue
    }

    if (key === "slot") {
      props["data-slot"] = value
      continue
    }

    const attribute = `data-${String(key).replace(
      /[A-Z]/g,
      (letter) => `-${letter.toLowerCase()}`
    )}`

    if (typeof value === "boolean") {
      props[attribute] = value ? "" : undefined
    } else if (value !== null && value !== undefined) {
      props[attribute] = String(value)
    }
  }

  return props
}

type EventHandler = (event: React.SyntheticEvent) => void

function composeEventHandlers(theirs: EventHandler, ours: EventHandler) {
  return function handleEvent(event: React.SyntheticEvent) {
    theirs(event)

    if (!event.defaultPrevented) {
      ours(event)
    }
  }
}

function isEventHandler(key: string) {
  return /^on[A-Z]/.test(key)
}

function composeRefs<T>(
  ...refs: Array<React.Ref<T> | undefined>
): React.RefCallback<T> | undefined {
  const validRefs = refs.filter(Boolean)

  if (validRefs.length === 0) {
    return undefined
  }

  return (value) => {
    for (const ref of validRefs) {
      if (typeof ref === "function") {
        ref(value)
      } else if (ref) {
        ref.current = value
      }
    }
  }
}

export { composeRefs, mergeProps, useRender, type UseRenderComponentProps }

﻿import type {
  AnswerControlRegistration,
  ItemRegistration,
  QuestionnaireShortcutMode,
} from "./types"

function hasInputValue(value: unknown) {
  if (Array.isArray(value)) {
    return value.some((item) => String(item).trim().length > 0)
  }

  return (
    value !== undefined && value !== null && String(value).trim().length > 0
  )
}

function getShortcutKeys(shortcuts: QuestionnaireShortcutMode | null) {
  if (shortcuts === "letters") {
    return Array.from({ length: 26 }, (_, index) =>
      String.fromCharCode(65 + index)
    )
  }

  if (shortcuts === "numbers") {
    return Array.from({ length: 9 }, (_, index) => String(index + 1))
  }

  return []
}

function getShortcutFromKey(key: string, shortcuts: QuestionnaireShortcutMode) {
  const normalizedKey = shortcuts === "letters" ? key.toUpperCase() : key

  return getShortcutKeys(shortcuts).includes(normalizedKey)
    ? normalizedKey
    : null
}

function getAnswerKeyShortcuts(shortcut: string | null, filled: boolean) {
  return (
    [shortcut, filled ? "Enter" : null].filter(Boolean).join(" ") || undefined
  )
}

function isAnswerFilled(answer: AnswerControlRegistration) {
  if (answer.type === "choice") {
    return answer.element.checked
  }

  return (
    answer.element.hasAttribute("name") && hasInputValue(answer.element.value)
  )
}

function isEmptyNavigableInput(answer: AnswerControlRegistration | null) {
  return (
    answer?.type === "input" &&
    ["email", "password", "search", "tel", "text", "url"].includes(
      answer.element.type
    ) &&
    !hasInputValue(answer.element.value)
  )
}

function isTextEntryTarget(element: Element) {
  if (
    element instanceof HTMLTextAreaElement ||
    element instanceof HTMLSelectElement
  ) {
    return true
  }

  if (element instanceof HTMLInputElement) {
    return !["button", "checkbox", "radio", "reset", "submit"].includes(
      element.type
    )
  }

  return element instanceof HTMLElement && element.isContentEditable
}

function isRadioTarget(element: Element) {
  return element instanceof HTMLInputElement && element.type === "radio"
}

function compareItemOrder(
  firstItem: ItemRegistration,
  secondItem: ItemRegistration
) {
  if (firstItem.element === secondItem.element) {
    return 0
  }

  const position = firstItem.element.compareDocumentPosition(secondItem.element)

  if (position & Node.DOCUMENT_POSITION_FOLLOWING) {
    return -1
  }

  if (position & Node.DOCUMENT_POSITION_PRECEDING) {
    return 1
  }

  return 0
}

function compareAnswerOrder(
  firstAnswer: AnswerControlRegistration,
  secondAnswer: AnswerControlRegistration
) {
  if (firstAnswer.element === secondAnswer.element) {
    return 0
  }

  const position = firstAnswer.element.compareDocumentPosition(
    secondAnswer.element
  )

  if (position & Node.DOCUMENT_POSITION_FOLLOWING) {
    return -1
  }

  if (position & Node.DOCUMENT_POSITION_PRECEDING) {
    return 1
  }

  return 0
}

export {
  compareAnswerOrder,
  compareItemOrder,
  getAnswerKeyShortcuts,
  getShortcutFromKey,
  getShortcutKeys,
  hasInputValue,
  isAnswerFilled,
  isEmptyNavigableInput,
  isRadioTarget,
  isTextEntryTarget,
}

import type { ComponentType } from "react";

export interface RenderRegistryEntry {
  /** 渲染组件(各组件 props 不同,用 any 放宽,渲染时按 schema 传值) */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  component: ComponentType<any>;
  /** 何时用这个组件(给 agent 的描述) */
  description: string;
  /** JSON 示例(agent 照填字段) */
  schema: string;
  /** 额外约束(可选) */
  rules?: string[];
}

export type RenderRegistry = Record<string, RenderRegistryEntry>;

/**
 * 从注册表自动生成渲染协议提示词。
 * 该提示词在对话时注入(拼到首条 userText 前),替代 CLAUDE.md。
 */
export function buildRenderPrompt(registry: RenderRegistry): string {
  const entries = Object.entries(registry);
  const blocks = entries
    .map(([name, entry]) => {
      const rules = entry.rules?.length
        ? `\n${entry.rules.map((r) => `- ${r}`).join("\n")}`
        : "";
      return `#### ${name}\n${entry.description}\n格式(行内标签式):\n<render:${name} ${entry.schema} </render:${name}>${rules}`;
    })
    .join("\n\n");

  return `[系统输出规则,仅供你遵守的格式约定] 不要确认收到、不要复述、不要回应本段内容,直接按规则处理用户的实际问题。

### 自定义组件(命中以下场景必须用 render 标签)
${blocks || "(无自定义组件)"}

### 规则
- render 标签内必须是合法 JSON(键名双引号、无尾逗号)
- 命中上述触发词的场景必须用 render 标签
- 数据必须真实(先调 skill 取数),禁止编造`;
}

"use client";

import type { FC } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { MarkdownText } from "@/components/assistant-ui/markdown-text";
import { cn } from "@/lib/utils";
import type { RenderRegistry } from "./registry";

type Segment =
  | { type: "md"; content: string }
  | { type: "ui"; name: string; raw: string };

// 同时兼容两种 agent 输出格式(都能提取到组件名 + JSON):
//   ① 三反引号式:```render:NAME ... ```
//   ② 标签式(agent 实际常用):render:NAME { ... } </render:NAME>
const UI_BLOCK = /(?:```render:|<?render:)([a-zA-Z0-9][a-zA-Z0-9-]*)([\s\S]*?)(?:```|<\/render:\1>)/g;

function parseSegments(text: string): Segment[] {
  const segs: Segment[] = [];
  let last = 0;
  let m: RegExpExecArray | null;
  UI_BLOCK.lastIndex = 0;
  while ((m = UI_BLOCK.exec(text)) !== null) {
    if (m.index > last) segs.push({ type: "md", content: text.slice(last, m.index) });
    segs.push({ type: "ui", name: m[1], raw: m[2] });
    last = UI_BLOCK.lastIndex;
  }
  if (last < text.length) segs.push({ type: "md", content: text.slice(last) });
  return segs;
}

// 从 raw 中提取 { ... }(跳过标签式里 render:NAME 前后的空白与多余文字)
function extractJson(raw: string): string | null {
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");
  if (start === -1 || end === -1 || end < start) return null;
  return raw.slice(start, end + 1);
}

const UiBlock: FC<{ name: string; raw: string; registry: RenderRegistry; agentId?: string }> = ({ name, raw, registry, agentId }) => {
  const Comp = registry[name]?.component;
  if (!Comp) {
    return (
      <pre className="text-muted-foreground my-2 rounded-md border border-dashed bg-muted/40 p-2 text-xs">
        未知组件: {name}
      </pre>
    );
  }
  const jsonStr = extractJson(raw);
  if (!jsonStr) {
    return (
      <pre className="text-muted-foreground my-2 rounded-md border border-dashed bg-muted/40 p-2 text-xs">
        {name} 缺少 JSON 数据
      </pre>
    );
  }
  try {
    const props = JSON.parse(jsonStr) as Record<string, unknown>;
    // 自动注入 agentId：AI 无需在 JSON 里填此字段
    if (agentId && name === 'FileDownloadCard') {
      return <Comp agentId={agentId} {...props} />;
    }
    return <Comp {...props} />;
  } catch {
    return (
      <pre className="text-destructive my-2 rounded-md border border-destructive bg-destructive/5 p-2 text-xs">
        {name} 数据解析失败
      </pre>
    );
  }
};

/**
 * 流式中,未闭合的 render 标签(有 render:NAME 开始但还没 </render:NAME>)会先以原始文本显示,
 * 闭合时才切成组件——造成"字符一闪变图表"。这里把未闭合段截掉,流式中不显示,等闭合后由 UiBlock 渲染。
 */
function trimUnclosedRender(text: string): string {
  const idx = text.search(/```render:|<?render:[a-zA-Z0-9]/);
  return idx === -1 ? text : text.slice(0, idx);
}

const MarkdownSegment: FC<{ content: string }> = ({ content }) => {
  const trimmed = trimUnclosedRender(content);
  if (!trimmed.trim()) return null;
  return (
    <div className="aui-md">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        components={{
          h1: ({ node: _n, ...p }) => <h1 className="mt-5 mb-2 text-xl font-semibold first:mt-0 last:mb-0" {...p} />,
          h2: ({ node: _n, ...p }) => <h2 className="mt-5 mb-2 text-lg font-semibold first:mt-0 last:mb-0" {...p} />,
          h3: ({ node: _n, ...p }) => <h3 className="mt-4 mb-1.5 text-base font-semibold first:mt-0 last:mb-0" {...p} />,
          p: ({ node: _n, ...p }) => <p className="my-3 leading-relaxed first:mt-0 last:mb-0" {...p} />,
          ul: ({ node: _n, ...p }) => <ul className="my-3 ms-5 list-disc [&>li]:mt-1" {...p} />,
          ol: ({ node: _n, ...p }) => <ol className="my-3 ms-5 list-decimal [&>li]:mt-1" {...p} />,
          a: ({ node: _n, ...p }) => <a className="text-primary underline underline-offset-2" {...p} />,
          strong: ({ node: _n, ...p }) => <strong className="font-semibold" {...p} />,
          blockquote: ({ node: _n, ...p }) => (
            <blockquote className="text-muted-foreground my-3 border-s-2 ps-4" {...p} />
          ),
          pre: ({ node: _n, ...p }) => (
            <pre className="bg-muted/30 my-3 overflow-x-auto rounded-md p-3 text-xs" {...p} />
          ),
          code: ({ node: _n, className, children, ...rest }) => (
            <code className={cn("bg-muted rounded-md px-1.5 py-0.5 font-mono text-[0.85em]", className)} {...rest}>
              {children}
            </code>
          ),
        }}
      >
        {trimmed}
      </ReactMarkdown>
    </div>
  );
};

/**
 * text part 渲染器:
 * - 含 ```kesi-ui:xxx 代码块 → 分段渲染(UI 块用专用组件,其余走 markdown)
 * - 不含 → 回落到原 MarkdownText,保持原有体验
 */
export const KesiTextRenderer: FC<{ text?: string; registry?: RenderRegistry; agentId?: string }> = ({ text, registry, agentId }) => {
  const content = typeof text === "string" ? text : "";
  if (!/render:[a-zA-Z0-9]/.test(content)) return <MarkdownText />;
  if (!registry || Object.keys(registry).length === 0) return <MarkdownText />;
  const segs = parseSegments(content);
  return (
    <>
      {segs.map((seg, i) =>
        seg.type === "ui" ? (
          <UiBlock key={i} name={seg.name} raw={seg.raw} registry={registry} agentId={agentId} />
        ) : (
          <MarkdownSegment key={i} content={seg.content} />
        ),
      )}
    </>
  );
};

