      const formatted = unstable_formatInteractableSnapshot(item);
      console.log('[enrichWithInteractables] snapshot', item.name, ':', formatted.slice(0, 120));
      snapshots.push(formatted);
    }
  }
  if (snapshots.length === 0) {
    console.log('[enrichWithInteractables] no snapshots, returning original text');
    return userText;
  }
  const result = '{##' + snapshots.join('\n') + '##}\n\n' + userText;
  console.log('[enrichWithInteractables] enriched text length:', result.length);
  return result;
}

// ====== useAgentRuntime ======

export const useAgentRuntime = (options?: {
  agentId?: string;
  preamble?: string;
  environmentVars?: Array<{ key: string; value: any }>;
  renderRegistry?: RenderRegistry;
  onShareThread?: (messages: readonly ThreadMessage[]) => void;
  initialThreadId?: string;
  onThreadChange?: (threadId: string | undefined) => void;
  onAgentChange?: (agentId: string) => void;
  onSendMessageBody?: (body: Record<string, any>, info: { sessionId: string; userText: string; url: string; headers: Record<string, string> }) => Record<string, any> | Promise<Record<string, any>>;
  /** 是否为 task runtime（默认 agent runtime），会改变所有请求地址 */
  isTaskRuntime?: boolean;
}) => {
  const { preamble, environmentVars, renderRegistry, onShareThread, initialThreadId, onThreadChange, onAgentChange, onSendMessageBody, isTaskRuntime } = options ?? {};
  const [agentId, setAgentId] = useState(options?.agentId ?? '');

  const [messages, setMessages] = useState<ThreadMessage[]>([]);
  const [isRunning, setIsRunning] = useState(false);
  const [threads, setThreads] = useState<Array<{
    status: 'regular';
    id: string;
    remoteId?: string;
    title?: string;
  }>>([]);
  const [currentThreadId, setCurrentThreadIdState] = useState<string | undefined>(initialThreadId);
  // 权威 sessionId：与 currentThreadId 同步，供 attachmentAdapter 实时读取（effect 之前即可用）
  const sessionIdRef = useRef<string | undefined>(currentThreadId);
  const setCurrentThreadId = useCallback((id: string | undefined) => {
    setCurrentThreadIdState(id);
    sessionIdRef.current = id;
    onThreadChange?.(id);
  }, [onThreadChange]);
  const [requestedBy] = useState('kesi-ui');
  const [toolStatuses, setToolStatuses] = useState<Record<string, ToolExecutionStatus>>({});
  const [loading, setLoading] = useState(false);
  const [threadsLoading, setThreadsLoading] = useState(false);

  // 询问模式：待答复的交互请求（permission-request / elicitation-request）
  const [interactionRequests, setInteractionRequests] = useState<AgentInteractionRequest[]>([]);

  // renderRegistry 用 ref 存,onNew 闭包读取,避免依赖变化导致重建。
  // 采用"按需注册"：ai-agent 不强 import 任何 render 组件，完全由调用方通过 renderRegistry
  // prop 传入各 render 组件自带的注册条目（component+description+schema+rules）。
  const renderRegistryRef = useRef<RenderRegistry | undefined>(renderRegistry);
  renderRegistryRef.current = renderRegistry;

  // preamble 从 context 读取，用 ref 存以保持闭包中的稳定性
  const preambleRef = useRef<string | undefined>(preamble);
  preambleRef.current = preamble;

  // environmentVars 从 context 读取，用 ref 存以保持闭包中的稳定性
  const environmentVarsRef = useRef<Array<{ key: string; value: any }> | undefined>(environmentVars);
  environmentVarsRef.current = environmentVars;

  const onSendMessageBodyRef = useRef<typeof onSendMessageBody>(onSendMessageBody);
  onSendMessageBodyRef.current = onSendMessageBody;

  const runIdRef = useRef<string | null>(null);
  const abortRef = useRef<AbortController | null>(null);
  const isNewSessionRef = useRef(false);        // onNew 新建 session 时屏蔽 useEffect 加载
  const pollingRef = useRef<{ messageId: string; timer: ReturnType<typeof setInterval> } | null>(null);

  // isTaskRuntime 用 ref 存，闭包中读取最新值
  const isTaskRuntimeRef = useRef<boolean | undefined>(isTaskRuntime);
  isTaskRuntimeRef.current = isTaskRuntime;

  // 根据 isTaskRuntime 选择 API 前缀和对应的 API 实例
  // task 模式下没有 agent-sessions / agent-messages 这些资源：Task 本身就是会话线程，
  // 统一走 eap/tasks，消息接口为 /eap/tasks/{id}/messages、/eap/tasks/{id}/messages/{messageId}
  const apiPrefix = isTaskRuntime ? 'task' : 'agent';
  const agentApi = useMemo(() => createAPI({ name: isTaskRuntime ? 'eap/tasks' : `eap/${apiPrefix}s` }), [apiPrefix, isTaskRuntime]);
  const sessionApi = useMemo(() => createAPI({ name: isTaskRuntime ? 'eap/tasks' : `eap/${apiPrefix}-sessions` }), [apiPrefix, isTaskRuntime]);
  const messageApi = useMemo(() => createAPI({ name: isTaskRuntime ? 'eap/tasks' : `eap/${apiPrefix}-messages` }), [apiPrefix, isTaskRuntime]);

  // attachmentAdapter 在 hook 内实例化，根据 isTaskRuntime 选择 API 前缀
  const attachmentAdapterRef = useRef<SessionAttachmentAdapter>(new SessionAttachmentAdapter(isTaskRuntime));
  const attachmentAdapter = attachmentAdapterRef.current;

  const runtime = useRef<AssistantRuntime>(null as any);

  // ---------- 初始加载 thread 列表 ----------
  useEffect(() => {
    setThreadsLoading(true);
    // task 模式：Task 即会话线程，通过 GET /eap/tasks 查任务列表；agent 模式：查某 agent 的会话列表
    const listPromise = isTaskRuntime
      ? sessionApi.fetch('', { method: 'GET' })
      : agentApi.fetch(`/${agentId}/sessions`, { method: 'GET' });
    listPromise.then(({ json }) => {
      const list = (json as any[]).slice().sort((a, b) =>
        new Date(b.createdAt ?? b.updatedAt ?? 0).getTime() -
        new Date(a.createdAt ?? a.updatedAt ?? 0).getTime()
      );
      setThreads(list.map((s: any) => ({
        status: 'regular' as const,
        id: s.id,
        remoteId: s.id,
        title: s.title ?? s.name,
      })));
      setThreadsLoading(false);
    }).catch(() => setThreadsLoading(false));
    if (!initialThreadId) {
      setCurrentThreadId(undefined);
    }
  }, [agentId, isTaskRuntime, initialThreadId, sessionApi, agentApi]);

  // ---------- thread 切换时加载消息，并轮询 running 的 assistant message ----------
  useEffect(() => {
    // 清除旧轮询
    if (pollingRef.current) {
      clearInterval(pollingRef.current.timer);
      pollingRef.current = null;
    }

    attachmentAdapter.setSessionId(currentThreadId);
    if (!currentThreadId) {
      setMessages([]);
      return;
    }
    // onNew 刚新建 session，消息由乐观插入 + SSE 驱动，跳过加载
    if (isNewSessionRef.current) {
      isNewSessionRef.current = false;
      return;
    }
    setLoading(true);
    sessionApi.fetch(`/${currentThreadId}/messages`, { method: 'GET' })
      .then(({ json }) => {
        const raw = json as AgentSessionMessage[];
        const msgs = raw.map(toThreadMessage).filter((m): m is ThreadMessage => m != null);
        setMessages(msgs);
        setLoading(false);

        // 检查最后一个 assistant message 是否 running → 启动轮询
        const lastAssistant = raw.filter(m => m.role === 'assistant').at(-1);
        if (lastAssistant && lastAssistant.id && (lastAssistant.status === 'running' || lastAssistant.status === 'queued')) {
          const timer = setInterval(async () => {
            try {
              // task 模式：消息详情接口为 GET /eap/tasks/{id}/messages/{messageId}
              const { json: updated } = await messageApi.fetch(
                isTaskRuntime ? `/${currentThreadId}/messages/${lastAssistant.id}` : `/${lastAssistant.id}`,
                { method: 'GET' },
              );
              const msg = toThreadMessage(updated as AgentSessionMessage);
              if (msg) {
                setMessages(prev => prev.map(m => m.id === msg.id ? msg : m));
                // 如果消息已完成，停止轮询
                const status = (updated as AgentSessionMessage).status;
                if (status && !['running', 'queued'].includes(status)) {
                  clearInterval(timer);
                  if (pollingRef.current?.timer === timer) pollingRef.current = null;
                }
              }
            } catch { /* 静默失败 */ }
          }, 2000);
          pollingRef.current = { messageId: lastAssistant.id, timer };
        }
      })
      .catch(() => { setMessages([]); setLoading(false); });

    return () => {
      if (pollingRef.current) {
        clearInterval(pollingRef.current.timer);
        pollingRef.current = null;
      }
    };
  }, [currentThreadId]);

  // ---------- 同步 toolStatuses → messages 中 tool-call part 的状态 ----------
  useEffect(() => {
    if (Object.keys(toolStatuses).length === 0) return;
    setMessages(prev => prev.map(msg => {
      if (msg.role !== 'assistant') return msg;
      const content = msg.content.map(part => {
        if (part.type !== 'tool-call') return part;
        const status = toolStatuses[(part as any).toolCallId];
        if (!status) return part;
        return { ...part, status: { type: 'running' as const } } as ThreadAssistantMessagePart;
      });
      return { ...msg, content } as ThreadMessage;
    }));
  }, [toolStatuses]);

  // ---------- 会话创建（onNew 与 attachmentAdapter 共用，避免重复创建） ----------
  const pendingSessionRef = useRef<Promise<string> | null>(null);

  const createSession = useCallback(async (title: string): Promise<string> => {
    console.log('[createSession] creating new session...', { agentId, title });

    const createBody = {
      title: title.slice(0, 30),
      metadata: {},
      requestedBy,
    };
    // task 模式：Task 即会话线程，通过 POST /eap/tasks 创建。
    // 请求体为 entity.CreateTaskRequest（必填：assigneeId、assigneeType、data、title），
    // assigneeId 即 agentId，首条消息随后通过 messages 接口发送
    const { json } = isTaskRuntime
      ? await sessionApi.fetch('', {
          method: 'POST',
          body: JSON.stringify({
            title: title.slice(0, 30),
            assigneeId: agentId || '',
            assigneeType: 'agent', // agent 或 squad；assigneeId 传的是 agentId，故为 agent
            data: { test: "abc" }, // 先传个空对象，后续消息里再传实际数据
          }),
        })
      : await agentApi.fetch(`/${agentId}/sessions`, { method: 'POST', body: JSON.stringify(createBody) });
    const newId = (json.sessionId ?? json.id ?? json.taskId) as string;
    console.log('[createSession] session created', { newId, json });

    if (!newId) throw new Error("Failed to create session");

    setThreads(prev => [{
      status: 'regular' as const,
      id: newId,
      remoteId: newId,
      title: title.slice(0, 30),
    }, ...prev]);
    isNewSessionRef.current = true;
    setCurrentThreadId(newId);

    return newId;
  }, [agentId, isTaskRuntime, requestedBy, sessionApi, agentApi]);

  // 已有会话直接复用；无会话时创建（并发去重：多个附件同时上传只创建一个会话）
  const ensureSessionCreated = useCallback(async (title: string): Promise<string> => {
    if (sessionIdRef.current) return sessionIdRef.current;
    if (!pendingSessionRef.current) {
      pendingSessionRef.current = createSession(title).finally(() => {
        pendingSessionRef.current = null;
      });
    }
    return pendingSessionRef.current;
  }, [createSession]);

  // attachmentAdapter 会话来源：实时读取最新 sessionId；新会话发附件时自动创建
  attachmentAdapter.setSessionGetter(() => sessionIdRef.current);
  attachmentAdapter.setSessionCreator(() => ensureSessionCreated('新会话'));

  // ---------- 询问模式：交互请求处理与回复 ----------
  // 收到交互事件 → 入 state（同 requestId 去重）；供 UI 渲染卡片
  const handleInteractionRequest = useCallback((req: AgentInteractionRequest) => {
    setInteractionRequests(prev => {
      const exists = prev.some(r => r.messageId === req.messageId && r.requestId === req.requestId);
      if (exists) return prev;
      return [...prev, req];
    });
  }, []);

  // 用户作答后回复后端：POST /messages/{messageId}/permission-reply
  const replyInteraction = useCallback(async (
    request: AgentInteractionRequest,
    action: InteractionReplyAction,
    updatedInput?: Record<string, unknown>,
  ): Promise<void> => {
    if (!request.messageId || !request.requestId) {
      console.warn('[replyInteraction] missing messageId/requestId', request);
      return;
    }
    try {
      const replyApi = createAPI({ name: 'eap/messages' });
      const body: Record<string, unknown> = { requestId: request.requestId, action };
      if (updatedInput) body['updatedInput'] = updatedInput;
      // permission-reply：POST /eap/messages/{id}/permission-reply
      const resp = await replyApi.fetch(`/${request.messageId}/permission-reply`, {
        method: 'POST',
        body: JSON.stringify(body),
      });
      console.log('[replyInteraction] replied', { requestId: request.requestId, action, resp });
      // 成功后从待答复列表移除
      setInteractionRequests(prev =>
        prev.filter(r => !(r.messageId === request.messageId && r.requestId === request.requestId)),
      );
    } catch (err) {
      console.error('[replyInteraction] failed', err);
      throw err;
    }
  }, []);

  // ---------- onNew ----------
  const onNew = useCallback(async (message: AppendMessage) => {
    console.log('[onNew] === START ===', {
      currentThreadId,
      userText: message.content?.[0]?.type === 'text' ? message.content[0].text : '(empty)',
      timestamp: new Date().toISOString(),
    });
    console.log('[onNew] message', message);
    // 取消旧任务
    abortRef.current?.abort();

    const userText = message.content?.[0]?.type === 'text'
      ? message.content[0].text
      : (typeof message.content === 'string' ? message.content : '');
    if (!userText) {
      console.log('[onNew] userText empty, return');
      return;
    }

    // session 是持久会话：已有 threadId 直接复用，否则创建新会话。
    // 与附件上传共用 ensureSessionCreated，避免「先传附件后建会话」时重复创建
    const sessionId = await ensureSessionCreated(userText);

    const isNewThread = !currentThreadId; // 创建时的 currentThreadId 值
    console.log('[onNew] resolved sessionId', {
      sessionId,
      isNewThread,
    });

    // 乐观插入 user + assistant
    const userId = genId();
    const assistantId = genId();
    const runId = `run_${Date.now()}`;
    runIdRef.current = runId;

    console.log('[onNew] optimistic messages', { userId, assistantId, runId, userText });

    // userMsg = AppendMessage + userId
    const userMsg: ThreadMessage = { id: userId, ...message } as unknown as ThreadMessage;
    const assistantMsg: ThreadMessage = {
      id: assistantId, role: 'assistant',
      content: [{ type: 'text', text: '' }],
      status: { type: 'running' }, metadata: {},
    } as unknown as ThreadMessage;

    setMessages(prev => [...prev, userMsg, assistantMsg]);
    setIsRunning(true);

    // AbortController
    const ac = new AbortController();
    abortRef.current = ac;

    try {
      console.log('[onNew] start SSE stream...', { sessionId });
      const timing = await streamRunInSession({
        sessionId,
        signal: ac.signal,
        message: message,
        messages: isNewThread ? [] : messages,
        context: runtime.current?.thread.getModelContext(),
        requestedBy,
        renderRegistry: renderRegistryRef.current,
        preamble: preambleRef.current,
        environmentVars: environmentVarsRef.current,
        onSendMessageBody: onSendMessageBodyRef.current,
        isTaskRuntime: isTaskRuntimeRef.current,
        onInteractionRequest: handleInteractionRequest,
        onMessageChange(content) {
          // console.log('[onNew] SSE: content updated', { assistantId, parts: content.map(p => p.type) });
          setMessages(prev => prev.map(m =>
            m.id === assistantId
              ? { ...m, content } as ThreadMessage
              : m,
          ));
        },
      });

      // 标记 complete，写入 timing 供 MessageTiming 组件显示
      console.log('[onNew] SSE done, marking complete', { assistantId });
      setMessages(prev => prev.map(m =>
        m.id === assistantId
          ? { ...m, status: { type: 'complete' as const, reason: 'stop' as const }, metadata: { ...(m.metadata as any), timing } } as ThreadMessage
          : m,
      ));
    } catch (err) {
      console.log('[onNew] error during SSE stream', { err, sessionId });
      throw err;
    } finally {
      console.log('[onNew] === END ===', { isRunning: false, sessionId });
      setIsRunning(false);
      runIdRef.current = null;
      abortRef.current = null;
    }
  }, [agentId, requestedBy, currentThreadId, messages, ensureSessionCreated, handleInteractionRequest]);

  // ---------- onReload ----------
  const onReload = useCallback(async (_parentId: string | null, _config: any) => {
    if (!currentThreadId) return;

    abortRef.current?.abort();

    setIsRunning(true);
    const assistantId = genId();
    const runId = `run_${Date.now()}`;
    runIdRef.current = runId;

    // 追加一条空的 assistant（reload 通常不新增 user 消息）
    setMessages(prev => [...prev, {
      id: assistantId, role: 'assistant',
      content: [{ type: 'text', text: '' }],
      status: { type: 'running' }, metadata: {},
    } as unknown as ThreadMessage]);

    const ac = new AbortController();
    abortRef.current = ac;

    try {
      // reload = 用最后一条 user 文本重新触发
      const lastUserText = messages.filter(m => m.role === 'user').at(-1);
      const userText = typeof lastUserText?.content === 'string'
        ? lastUserText.content
        : (lastUserText?.content?.[0] as any)?.text ?? '';

      if (!userText) return;

      const timing = await streamRunInSession({
        sessionId: currentThreadId,
        signal: ac.signal,
        message: { content: [{ type: 'text' as const, text: userText }], parentId: null, sourceId: null, runConfig: undefined } as unknown as AppendMessage,
        messages,
        context: runtime.current?.thread.getModelContext(),
        requestedBy,
        renderRegistry: renderRegistryRef.current,
        preamble: preambleRef.current,
        environmentVars: environmentVarsRef.current,
        onSendMessageBody: onSendMessageBodyRef.current,
        isTaskRuntime: isTaskRuntimeRef.current,
        onInteractionRequest: handleInteractionRequest,
        onMessageChange(content) {
          setMessages(prev => prev.map(m =>
            m.id === assistantId
              ? { ...m, content } as ThreadMessage
              : m,
          ));
        },
      });

      setMessages(prev => prev.map(m =>
        m.id === assistantId
          ? { ...m, status: { type: 'complete' as const, reason: 'stop' as const }, metadata: { ...(m.metadata as any), timing } } as ThreadMessage
          : m,
      ));
    } finally {
      setIsRunning(false);
      runIdRef.current = null;
      abortRef.current = null;
    }
  }, [currentThreadId, messages, requestedBy, handleInteractionRequest]);

  // ---------- onEdit ----------
  const onEdit = useCallback(async (editMessage: AppendMessage) => {
    if (!currentThreadId) return;

    abortRef.current?.abort();

    setIsRunning(true);
    const assistantId = genId();
    const runId = `run_${Date.now()}`;
    runIdRef.current = runId;

    // 追加一条编辑后的 user + 新 assistant running
    const editUserId = genId();
    setMessages(prev => [...prev, {
      id: editUserId,
      ...editMessage
    } as unknown as ThreadMessage, {
      id: assistantId, role: 'assistant',
      content: [{ type: 'text', text: '' }],
      status: { type: 'running' }, metadata: {},
    } as unknown as ThreadMessage]);

    const ac = new AbortController();
    abortRef.current = ac;

    try {
      const timing = await streamRunInSession({
        sessionId: currentThreadId,
        signal: ac.signal,
        message: editMessage,
        messages,
        context: runtime.current?.thread.getModelContext(),
        requestedBy,
        renderRegistry: renderRegistryRef.current,
        preamble: preambleRef.current,
        environmentVars: environmentVarsRef.current,
        onSendMessageBody: onSendMessageBodyRef.current,
        isTaskRuntime: isTaskRuntimeRef.current,
        onInteractionRequest: handleInteractionRequest,
        onMessageChange(content) {
          setMessages(prev => prev.map(m =>
            m.id === assistantId
              ? { ...m, content } as ThreadMessage
              : m,
          ));
        },
      });

      setMessages(prev => prev.map(m =>
        m.id === assistantId
          ? { ...m, status: { type: 'complete' as const, reason: 'stop' as const }, metadata: { ...(m.metadata as any), timing } } as ThreadMessage
          : m,
      ));
    } finally {
      setIsRunning(false);
      runIdRef.current = null;
      abortRef.current = null;
    }
  }, [currentThreadId, requestedBy, messages, handleInteractionRequest]);

  // ---------- onCancel ----------
  const onCancel = useCallback(async () => {
    abortRef.current?.abort();

    // 如果后端有 cancel endpoint 可以在这调用
    // const runId = runIdRef.current;
    // if (runId) { ... }

    setIsRunning(false);
    runIdRef.current = null;
  }, []);

  // ---------- store ----------
  const store: ExternalStoreAdapter = {
    messages,
    isRunning,
    onNew,
    onEdit,
    onReload,
    onCancel,
    isLoading: loading,
    extras: {
      agentId,
      setAgentId: (id: string) => {
        setAgentId(id);
        onAgentChange?.(id);
      },
      preamble,
      renderRegistry,
      onShareThread,
      isTaskRuntime,
      loading,
      threadsLoading,
      interactionRequests,
      replyInteraction,
    },
    unstable_enableToolInvocations: true,
    onAddToolResult: (options) => {
      cacheToolResult(options);
    },
    setToolStatuses: (statuses) => { setToolStatuses(statuses); },

    adapters: {
      threadList: {
        threadId: currentThreadId,
        isLoading: threadsLoading,
        threads,
        onSwitchToThread: async (id) => { setCurrentThreadId(id); },
        onSwitchToNewThread: async () => { setCurrentThreadId(undefined); },
        onRename: async (id, title) => {
          await sessionApi.fetch(`/${id}`, {
            method: 'PATCH',
            body: JSON.stringify({ title }),
          });
          setThreads(prev => prev.map(t => t.id === id ? { ...t, title } : t));
        },
        onArchive: async (id) => {
          await sessionApi.fetch(`/${id}`, {
            method: 'PATCH',
            body: JSON.stringify({ status: 'archived' }),
          });
          setThreads(prev => prev.filter(t => t.id !== id));
        },
        onDelete: async (id) => {
          await sessionApi.fetch(`/${id}`, { method: 'DELETE' });
          if (currentThreadId === id) setCurrentThreadId(undefined);
          setThreads(prev => prev.filter(t => t.id !== id));
        },
      },
      attachments: attachmentAdapter,
      dictation: dictationAdapter,
      speech: speechAdapter,
      feedback: feedbackAdapter,
    },
  } as ExternalStoreAdapter;

  runtime.current = useExternalStoreRuntime(store);
  return runtime.current;
};

// ====== useReadOnlyRuntime ======

/**
 * 只读模式 Runtime — 将后端消息转为只读 AssistantRuntime
 * 用于会话管理中的详情弹窗，仅展示历史记录，不发送消息
 */
export function useReadOnlyRuntime(messages: AgentSessionMessage[]): AssistantRuntime {
  const store = useMemo<ExternalStoreAdapter>(() => {
    if (!messages || messages.length === 0) {
      return {
        messages: [],
        isRunning: false,
        onNew: async () => {},
        onEdit: async () => {},
        onReload: async () => {},
        onCancel: async () => {},
        onCopy: async () => true,
        onNewThread: async () => {},
        onSwitchThread: async () => {},
        onAddToolResult: () => {},
      };
    }

    const threadMessages = messages
      .map(toThreadMessage)
      .filter((m): m is ThreadMessage => m !== null);

    return {
      messages: threadMessages,
      isRunning: false,
      onNew: async () => {},
      onEdit: async () => {},
      onReload: async () => {},
      onCancel: async () => {},
      onCopy: async () => true,
      onNewThread: async () => {},
      onSwitchThread: async () => {},
      onAddToolResult: () => {},
    };
  }, [messages]);

  return useExternalStoreRuntime(store);
}

"use client";

import {
  unstable_useInteractable,
  unstable_useInteractableVersions,
  unstable_interactableTool,
  defineToolkit,
} from "@assistant-ui/react";
import { createContext, useContext, type FC } from "react";

/**
 * 可交互任务看板组件。
 * 模型通过 `update_taskBoard` 工具读写任务列表，用户也可以直接勾选。
 */
export const TaskBoard: FC = () => {
  const [state, { setState }] = unstable_useInteractable(
    "taskBoard",
    {
      description:
        "任务看板。模型通过 update_taskBoard 工具管理任务：add / update / remove / clear。新任务 title 必填，done=false。",
      stateSchema: {
        type: "object",
        properties: {
          tasks: {
            type: "array",
            items: {
              type: "object",
              properties: {
                id: { type: "string" },
                title: { type: "string" },
                done: { type: "boolean" },
              },
              required: ["id", "title", "done"],
            },
          },
        },
        required: ["tasks"],
      },
      initialState: { tasks: [{ id: "1", title: "示例任务", done: false }] },
    },
  );

  const tasks: { id: string; title: string; done: boolean }[] =
    (state as any)?.tasks ?? [];

  return (
    <div className="mx-auto mb-2 w-full max-w-(--thread-max-width) rounded-lg border p-3 text-sm">
      <h4 className="mb-2 flex items-center gap-1.5 font-medium">
        <span>📋</span> 任务看板
      </h4>
      {tasks.length === 0 ? (
        <p className="text-muted-foreground text-xs">
          暂无任务，让 AI 帮你添加吧
        </p>
      ) : (
        <ul className="space-y-1">
          {tasks.map((t) => (
            <li key={t.id} className="flex items-center gap-2">
              <input
                type="checkbox"
                checked={t.done}
                onChange={() =>
                  setState((prev: any) => ({
                    tasks: (prev.tasks ?? []).map((x: any) =>
                      x.id === t.id ? { ...x, done: !x.done } : x,
                    ),
                  }))
                }
                className="size-3.5"
              />
              <span
                className={
                  t.done ? "text-muted-foreground line-through" : ""
                }
              >
                {t.title}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

// ==================== Document Artifact ====================

type Document = {
  title?: string;
  content?: string;
};

const emptyDoc: Document = { title: "", content: "" };

/** 文档上下文：当前选中的 artifact ID */
export const DocumentCtx = createContext<{
  documentId: string | undefined;
  setDocumentId: (id: string | undefined) => void;
}>({ documentId: undefined, setDocumentId: () => {} });

/** 包装 DocumentButton 自动读取 Context 并设置 documentId */
export const DocumentWithCtx: FC<{
  state: Document;
  version?: { isLatest: boolean };
  id?: string;
}> = (props) => {
  const { setDocumentId } = useContext(DocumentCtx);
  console.log("DocumentWithCtx props", props);
  return (
    <DocumentButton
      {...props}
      onClick={() => {
        setDocumentId(props.id);
      }}
    />
  );
};

/** 文档编辑器（全尺寸面板） */
export const DocumentEditor: FC<{ id?: string }> = ({ id }) => {
  const [state, { setState }] = unstable_useInteractable("document", {
    id,
    description: "用户可编辑的文档。创建时 content 必填，title 可选。",
    stateSchema: {
      type: "object",
      properties: {
        title: { type: "string" },
        content: { type: "string" },
      },
    },
    initialState: emptyDoc,
  });

  const versions = unstable_useInteractableVersions<Document>(id ?? "", "document");
  const doc: Document = (state ?? emptyDoc) as Document;

  return (
    <div className="mx-auto my-2 w-full max-w-(--thread-max-width) rounded-lg border p-4 text-sm">
      <div className="mb-3 flex items-center gap-2">
        <span>📝</span>
        <input
          value={doc.title ?? ""}
          onChange={(e) => setState((prev: any) => ({ ...prev, title: e.target.value }))}
          placeholder="文档标题"
          className="flex-1 bg-transparent text-base font-semibold outline-none placeholder:text-muted-foreground/50"
        />
        {versions.length > 0 && (
          <div className="relative shrink-0">
            <select
              value=""
              onChange={(e) => {
                const idx = parseInt(e.target.value, 10);
                if (!isNaN(idx)) versions[idx]?.restore();
              }}
              className="text-muted-foreground hover:text-foreground cursor-pointer appearance-none rounded border-0 bg-transparent pr-4 text-xs underline decoration-dotted underline-offset-2 transition-colors"
            >
              <option value="" disabled>{versions.length} 个版本</option>
              {versions.map((v, i) => (
                <option key={i} value={i}>
                  v{i + 1} — {v.origin === "user-edit" ? "用户编辑" : "AI 创建"}
                </option>
              ))}
            </select>
          </div>
        )}
      </div>
      <textarea
        value={doc.content ?? ""}
        onChange={(e) => setState((prev: any) => ({ ...prev, content: e.target.value }))}
        placeholder="在此输入文档内容..."
        rows={12}
        className="text-foreground w-full resize-y rounded-md border bg-transparent p-3 text-sm leading-relaxed outline-none transition-colors focus:border-blue-500 placeholder:text-muted-foreground/50"
      />
    </div>
  );
};

/** 文档选择按钮（内联渲染） */
const DocumentButton: FC<{
  state: Document;
  version?: { isLatest: boolean };
  onClick?: () => void;
}> = ({ state, version, onClick }) => {
  const isReadOnly = version ? !version.isLatest : false;
  const preview = (state.content ?? "").slice(0, 80);

  return (
    <button
      type="button"
      onClick={() => onClick?.()}
      className="mx-auto my-2 w-full min-h-4 max-w-(--thread-max-width) rounded-lg border p-3 text-left text-sm transition-colors hover:bg-accent"
    >
      <div className="mb-1 flex items-center gap-2">
        <span>📄</span>
        <span className="font-medium">{state.title || "无标题"}</span>
        {isReadOnly && <span className="text-muted-foreground text-xs">（历史版本）</span>}
      </div>
      <p className="text-muted-foreground line-clamp-2 text-xs">{preview || "空文档"}</p>
    </button>
  );
};

/** 文档 artifact toolkit */
